EXPECTED_STEP={'operations': 79082, 'register_peak': 1927, 'bytes': 276745, 'sha256': 'f8c0e248b32abe2fd51d2b1db9f2a25354a65eed2ab6c860b0ec0068e11caf48', 'chained_table_checksum': 'c8fa4bd9170966dc', 'prefilter': {'bytes': 49, 'destination': 1931, 'forms': {14: 0, 25: 14, 36: 1}, 'operations': 15, 'sha256': '02ffc1321a5ab8263554046357c9cc8a07f7692f001765a54031b45e95fbe1cc', 'short': 14}}
LINK_REGISTER=1926
EXPECTED_CONTROLLER={'bytes': 8336, 'capacity': 93000, 'counts': {'ctz_clear': 44, 'deadline_final': 1, 'dp_fixed': 2893, 'eval_f': 3823, 'gather': 2308, 'hit': 125, 'insert': 8, 'instructions': 994, 'output_message': 27, 'probe_word': 24, 'record_slot': 13, 'replay_const': 3916, 'replay_g': 11489, 'replay_nck': 17, 'replay_rate': 7663, 'restart': 2835, 'restart_halt': 3, 'restore': 257, 'setup': 750162, 'setwalk': 2822}, 'instructions': 994, 'literal_count': 12, 'memory_words': 19128, 'register_words': 1938, 'round': 14, 'sha256': 'd9929b3bbc73fb6cae81e61b3b33253281e1de454e654b2770c49a23ddccb5e7', 'table_words': 18600}
CONSTANTS=tuple(int(x,16) for x in RECORD['constants'])
PD=tuple(int(x,16) for x in ['623e904fa6d5399a', 'c847d00a61434286', '08814400292042e6', '1580273008228448'])

def unpack(name):return lzma.decompress(base64.b85decode(SOURCES[name])).decode()
CERT=json.loads(unpack('certificate'))
PARAMETERS=CERT['parameters']
HIT_LIMIT=CERT['hit_limit']
def load_modules():
 step=types.ModuleType('normative_step');exec(compile(unpack('step'),'normative_step.py','exec'),step.__dict__)
 base=types.ModuleType('emitter');sys.modules['emitter']=base;exec(compile(unpack('controller_base'),'controller_base.py','exec'),base.__dict__)
 ctl=types.ModuleType('normative_controller');exec(compile(unpack('controller'),'normative_controller.py','exec'),ctl.__dict__)
 support=types.ModuleType('experiment_support');exec(compile(unpack('support'),'experiment_support.py','exec'),support.__dict__)
 model=types.ModuleType('certificate_model');exec(compile(unpack('model'),'certificate_model.py','exec'),model.__dict__)
 return step,ctl,support,model

RECORD['plan']=unpack('plan')

def checks(certificate=False):
 step,ctl,support,model=load_modules()
 step_binary,pd,meta=support.step_checks(step,RECORD,EXPECTED_STEP)
 if tuple(pd)!=PD:raise AssertionError('step PD')
 manifest=ctl.manifest(RECORD['round'],PARAMETERS['S'],LINK_REGISTER,PARAMETERS,HIT_LIMIT)
 for key in ('instructions','bytes','sha256','literal_count','register_words'):
  if manifest[key]!=EXPECTED_CONTROLLER[key]:raise AssertionError('controller '+key)
 support.controller_checks(ctl,manifest,CONSTANTS,PD,PARAMETERS)
 if certificate:
  if hashlib.sha256(RECORD['plan'].encode()).hexdigest()!=CERT['plan_sha256']:raise AssertionError('plan binding')
  parts=model.success_parts(PARAMETERS,PARAMETERS['U'],CERT['key_bits'])
  if CERT['hit_limit']!=parts['hit_limit'] or CERT['hit_abort']!=parts['hit_abort']:raise AssertionError('hit certificate binding')
  inputs=CERT['probability_inputs'];pre=CERT['preconditions'];audit=CERT['rounding_audit'];Decimal=__import__('decimal').Decimal;aux=parts['aux'];M=Decimal(2)**256
  expected_inputs={'theta_numerator':PARAMETERS['DT'],'theta_denominator_bits':PARAMETERS['HF']+PARAMETERS['DK'],
   'evaluations':256*PARAMETERS['Tb'],'mean_dp':str(parts['mean_dp']),'available_restarts':PARAMETERS['U']-256,
   'prefilter_bits':16,'fresh_step_probability_exact':str(aux['fresh_step_exact']),
   'fresh_step_probability_upper':str(aux['fresh_step_upper']),'fresh_hit_mean_upper':str(parts['hit_mean']),
   'fresh_hit_threshold':int(aux['fresh_threshold']),'fresh_hit_delta':str(aux['fresh_delta']),
   'hit_chernoff_exponent':str(parts['hit_exponent']),'conditioning_start_term':str(aux['conditioning_start']),
   'conditioning_partition_term':str(aux['conditioning_partition']),'conditioning_dp_term':str(aux['conditioning_dp']),
   'conditioning_delta':str(aux['conditioning_delta']),'conditioning_inflation':str(aux['conditioning_inflation']),
   'conditioning_ratio':str(aux['conditioning_ratio']),'age_g6':str(aux['age_g6']),
   'coincidence_upper':str(aux['coincidence_upper']),
   'start_replay_union_bound':str(aux['start_replay_bound'])}
  if inputs!=expected_inputs:raise AssertionError('probability inputs')
  expected_pre={'available_gt_mean':Decimal(PARAMETERS['U']-256)>parts['mean_dp'],
   'fresh_step_probability_lt_2^-8':aux['fresh_step_exact']<Decimal(2)**-8,
   'fresh_hit_threshold_gt_mean':aux['fresh_threshold']>parts['hit_mean'],
   'fresh_hit_delta_gt_2^-20':aux['fresh_delta']>Decimal(2)**-20,
   'hit_threshold_equals_abort_minus_lrc':int(aux['fresh_threshold'])==CERT['hit_abort']-PARAMETERS['LRC'],
   'conditioning_delta_lt_2^-109':aux['conditioning_delta']<Decimal(2)**-109,
   'conditioning_ratio_le_1_plus_2^-108':aux['conditioning_ratio']<=Decimal(1)+Decimal(2)**-108,
   'evaluation_fraction_le_half':Decimal(256*PARAMETERS['Tb'])/M<=Decimal('.5'),
   'dp_partition_nonempty':parts['theta']*M>Decimal(PARAMETERS['U']) and (Decimal(1)-parts['theta'])*M>Decimal(256*PARAMETERS['Tb']),
   'start_replay_bound_le_2^-90':aux['start_replay_bound']<=Decimal(2)**-90,
   'bins_cover_replay_cap':PARAMETERS['J']*PARAMETERS['W']==PARAMETERS['LRC'],
   'replay_cap_below_deadline':PARAMETERS['LRC']<PARAMETERS['Tb'],'table_has_initial_walks':PARAMETERS['U']>=256}
  if pre!=expected_pre or not all(pre.values()):raise AssertionError('certificate precondition')
  expected_audit={'precision_digits':200,'operation_bound':aux['rounding_operations'],
   'per_operation_absolute_bound':str(aux['rounding_per_operation']),
   'accumulated_absolute_bound':str(aux['rounding_bound']),
   'accumulated_lt_2^-200':aux['rounding_bound']<Decimal(2)**-200,
   'charged_numeric_term':str(Decimal(2)**-60)}
  if audit!=expected_audit or not audit['accumulated_lt_2^-200'] or not Decimal(audit['accumulated_absolute_bound'])<Decimal(audit['charged_numeric_term']):raise AssertionError('rounding audit')
  lo=__import__('decimal').Decimal(CERT['covered_success']['lower']);hi=__import__('decimal').Decimal(CERT['covered_success']['upper'])
  if not lo<=parts['covered']<=hi:raise AssertionError('covered interval')
  if Decimal(CERT['margin_above_target'])!=parts['union']-Decimal('0.39'):raise AssertionError('comparator margin')
  for name,value in parts['failures'].items():
   item=CERT['failure_intervals'][name]
   if not __import__('decimal').Decimal(item['lower'])<=value<=__import__('decimal').Decimal(item['upper']):raise AssertionError(name)
  if not parts['union']>=__import__('decimal').Decimal(CERT['union_lower'])>=__import__('decimal').Decimal('0.39')>parts['previous']:
   raise AssertionError('success certificate')
 return support,manifest

def main():
 if len(sys.argv)>1 and sys.argv[1]=='--self-test':
  support,manifest=checks(True);print(json.dumps({'status':'ok','step':EXPECTED_STEP,'controller':{k:manifest[k] for k in ('instructions','bytes','sha256','literal_count')}},sort_keys=True));return
 request=json.load(sys.stdin);kind=request.get('experiment_id')
 if request.get('schema_version')!=1 or kind not in ('exact-controller','success-certificate'):raise ValueError('request')
 event={'kind':'digest-xor-mask','mask_hex':'ff0f'+'00'*30,'expected_hex':'00'*32}
 if request.get('target_profile')!='sha3-256-r14-prefix-v1' or request.get('event')!=event:raise ValueError('request event')
 support,manifest=checks(kind=='success-certificate');rows=[]
 left,right,evaluations=support.projection(request['trials'][0]['seed'],CONSTANTS,PD,RECORD['round'])
 for trial in request['trials']:
  rows.append({'trial':trial['trial'],'message_a_hex':left,'message_b_hex':right,
               'observations':{'evaluations':evaluations,'step_instructions':EXPECTED_STEP['operations'],
                               'controller_instructions':manifest['instructions'],'controller_paths':12,
                               'limit_halt_checked':1}})
 json.dump({'schema_version':1,'trials':rows},sys.stdout,sort_keys=True,separators=(',',':'))
if __name__=='__main__':main()
